import os
import psycopg2
import psycopg2.extras
from fastapi import FastAPI, HTTPException
from fastapi.responses import JSONResponse
from pydantic import BaseModel

app = FastAPI()

# Database connection helper
def get_connection():
    host = os.getenv("PGHOST")
    port = int(os.getenv("PGPORT", "5432"))
    dbname = os.getenv("PGDATABASE")
    user = os.getenv("PGUSER")
    password = os.getenv("PGPASSWORD")
    if not password:
        # Generate short‑lived credential using Databricks SDK
        try:
            from databricks.sdk import WorkspaceClient
            client = WorkspaceClient()
            cred = client.lakebase.get_temp_credentials(name=os.getenv("LAKEBASE_INSTANCE", ""))
            password = cred.password
        except Exception as e:
            raise RuntimeError(f"Unable to obtain password: {e}")
    return psycopg2.connect(host=host, port=port, dbname=dbname, user=user, password=password, cursor_factory=psycopg2.extras.RealDictCursor)

class TaskCreate(BaseModel):
    title: str

class TaskPatch(BaseModel):
    done: bool

@app.get("/health")
def health():
    return {"status": "ok"}

@app.get("/api/tasks")
def list_tasks():
    with get_connection() as conn:
        with conn.cursor() as cur:
            cur.execute("SELECT id, title, done, created_at FROM app.tasks ORDER BY id")
            rows = cur.fetchall()
    return rows

@app.post("/api/tasks", status_code=201)
def create_task(task: TaskCreate):
    with get_connection() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "INSERT INTO app.tasks (title) VALUES (%s) RETURNING id, title, done, created_at",
                (task.title,)
            )
            new_row = cur.fetchone()
            conn.commit()
    return new_row

@app.patch("/api/tasks/{task_id}")
def update_task(task_id: int, patch: TaskPatch):
    with get_connection() as conn:
        with conn.cursor() as cur:
            cur.execute(
                "UPDATE app.tasks SET done = %s WHERE id = %s RETURNING id, title, done, created_at",
                (patch.done, task_id)
            )
            updated = cur.fetchone()
            if not updated:
                raise HTTPException(status_code=404, detail="Task not found")
            conn.commit()
    return updated

if __name__ == "__main__":
    import uvicorn
    port = int(os.getenv("DATABRICKS_APP_PORT", "8000"))
    uvicorn.run(app, host="0.0.0.0", port=port)

